// Fixed toy models (generated by tests/fixtures/make_gguf_fixtures.py at
// build time and embedded by mayhem/harnesses/embed_models.py), loaded once
// per process. The model is never mutated after load; each input gets its
// own fresh session.
#pragma once
#include "fuzz_common.h"
#include "fuzz_models.inc"  // k_models[] = {name, bytes, size}

namespace fuzz {
inline transcribe_model * embedded_model(const char * name) {
    for (const auto & m : k_models) {
        if (std::strcmp(m.name, name) == 0) {
            transcribe_model * model = load_bytes(m.data, m.size, false);
            if (!model) {
                std::fprintf(stderr, "fuzz: embedded model %s failed to load\n", name);
                std::abort();
            }
            return model;
        }
    }
    std::fprintf(stderr, "fuzz: no embedded model %s\n", name);
    std::abort();
}
}  // namespace fuzz
